 struct Outputs{unsigned order=0,fullVoiceOrder=0,sampleOrder=0,fullPatchOrder=0,upperPatchOrder=0;uint8_t voice=0,sample=0;uint16_t address=0;uint32_t patch=0,upperPatch=0,payload=0;bool voiceKnown=false,sampleKnown=false,addressKnown=false,patchKnown=false,upperPatchKnown=false;Payload pitchPayload=Payload::Preserved;};
 struct Summary{Input input{};uint32_t expressionSource=0;uint8_t part=0,policy=0,mode=0,queue=0,ordered=0,octave=0,oldOctave=0,finalMode=0;bool policyRead=false,modeRead=false,queueRead=false,orderedRead=false,prepared=false,loop=false;unsigned emitted=0;Outputs outputs{};};
