 bool complete()const{return complete_;}bool critical()const{return component_==Component::Emit&&emit_->critical();}Component component()const{return component_;}uint32_t components()const{return components_;}const Effect&effect()const{return effect_;}const Summary&summary()const{return summary_;}const ArpEventTask&event()const{return event_;}const NativeArpEmitService*lastEmit()const{return emit_?&*emit_:nullptr;}
 template<class T>const T*task()const{if constexpr(std::is_same_v<T,NativeArpChordService>)return this;else if constexpr(std::is_same_v<T,PartLookupTask>){if(component_==Component::Lookup)return &*lookup_;return component_==Component::Emit?emit_->template task<T>():nullptr;}else if constexpr(std::is_same_v<T,ArpEventTask>)return component_==Component::Event?&event_:component_==Component::Emit?emit_->template task<T>():nullptr;else return component_==Component::Emit?emit_->template task<T>():nullptr;}
